}

#!/usr/bin/env node
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';

import { createServer } from './server.js';
import { hasApiKey } from './config.js';

async function main() {
  const server = createServer();
  const transport = new StdioServerTransport();
  await server.connect(transport);

  // stdout is reserved for JSON-RPC frames — all logging must go to stderr.
  console.error('[vision-bridge-mcp] ready on stdio (tools: analyze_image, ocr_image)');
  if (!hasApiKey()) {
    console.error(
      '[vision-bridge-mcp] warning: GEMINI_API_KEY is not set — tool calls will fail until ' +
        'it is configured. Get a free key at https://aistudio.google.com/apikey',
    );
  }
}

main().catch((err) => {
  console.error('[vision-bridge-mcp] fatal error during startup:', err);
  process.exitCode = 1;
});

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { z } from 'zod';

import { loadConfig } from './config.js';
import { validateAndReadImage } from './image-utils.js';
import { analyzeImageWithGemini } from './gemini-client.js';
import { VisionBridgeError } from './errors.js';

const DESCRIBE_DEFAULT_PROMPT =
  'Describe this image in detail for a software developer. If it contains source code, ' +
  'transcribe the code precisely (as a fenced code block). If it contains a UI, diagram, ' +
  'error message, or stack trace, describe its structure and transcribe any visible text. ' +
  'Otherwise, describe what the image shows and anything relevant to a coding task.';

const OCR_PROMPT =
  'Transcribe all text visible in this image exactly as it appears, preserving line breaks, ' +
  'indentation, and formatting as closely as possible. Output ONLY the transcribed text, ' +
  'with no commentary, preamble, or code fences.';

/**
 * Builds the vision-bridge-mcp server with its two tools registered.
 * Construction never touches the network or reads GEMINI_API_KEY — that
 * happens lazily inside each tool handler — so the server can start and
 * respond to `tools/list` even before the API key is configured.
 *
 * @returns {McpServer}
 */
export function createServer() {
  const server = new McpServer({
    name: 'vision-bridge-mcp',
    version: '0.1.0',
  });

  server.tool(
    'analyze_image',
    {
      image_path: z
        .string()
        .describe(
          'Path to a local image file (absolute, or relative to the directory OpenCode ' +
            'was started in). Supports PNG, JPEG, WEBP, GIF, HEIC/HEIF.',
        ),
      prompt: z
        .string()
        .optional()
        .describe(
          'Optional custom instruction for what to look for or how to describe the image. ' +
            'If omitted, a general developer-focused description is returned.',
        ),
    },
    async ({ image_path: imagePath, prompt }) =>
      runVisionTool({ imagePath, prompt: prompt && prompt.trim() ? prompt : DESCRIBE_DEFAULT_PROMPT }),
  );

  server.tool(
    'ocr_image',
    {
      image_path: z
        .string()
        .describe(
          'Path to a local image file to extract text from (absolute, or relative to the ' +
            'directory OpenCode was started in). Supports PNG, JPEG, WEBP, GIF, HEIC/HEIF.',
        ),
    },
    async ({ image_path: imagePath }) => runVisionTool({ imagePath, prompt: OCR_PROMPT }),
  );

  return server;
}

/**
 * Shared implementation for both tools: load config, validate + read the
 * image, call Gemini, and shape the result as an MCP tool response.
 * Every expected failure (bad path, missing key, upstream error) is
 * returned as `{ isError: true }` with a clear message rather than
 * thrown, so a single bad call never crashes the server process.
 *
 * @param {{ imagePath: string, prompt: string }} params
 */
async function runVisionTool({ imagePath, prompt }) {
  try {
    const config = loadConfig();
    const image = await validateAndReadImage(imagePath, { maxBytes: config.maxImageBytes });
    const text = await analyzeImageWithGemini({
      apiKey: config.apiKey,
      model: config.model,
      base64: image.base64,
      mimeType: image.mimeType,
      prompt,
    });

    return { content: [{ type: 'text', text }] };
  } catch (err) {
    if (err instanceof VisionBridgeError) {
      return { content: [{ type: 'text', text: `[${err.code}] ${err.message}` }], isError: true };
    }
    // Unexpected/unknown error — still report it as a tool error rather
    // than letting it propagate and take down the stdio connection.
    const message = err && err.message ? err.message : String(err);
    return {
      content: [{ type: 'text', text: `[UNEXPECTED_ERROR] ${message}` }],
      isError: true,
    };
  }
}
